CREATE TABLE rulebooks (id text NOT NULL, version text PRIMARY KEY, effective_from timestamptz NOT NULL, effective_until timestamptz, withdrawn_at timestamptz, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE substances (id text NOT NULL, version bigint NOT NULL, un_number text NOT NULL, payload jsonb NOT NULL, effective_from timestamptz NOT NULL, effective_until timestamptz, PRIMARY KEY (id, version));
CREATE TABLE manifest_revisions (manifest_id text NOT NULL, revision bigint NOT NULL, rulebook_version text NOT NULL REFERENCES rulebooks(version), input_digest text NOT NULL, state text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (manifest_id, revision));
CREATE TABLE validation_results (id text PRIMARY KEY, manifest_id text NOT NULL, revision bigint NOT NULL, rulebook_version text NOT NULL, input_digest text NOT NULL, decision text NOT NULL, payload jsonb NOT NULL, evaluated_at timestamptz NOT NULL);
CREATE TABLE audit_events (id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, resource text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
